```rust
#[test]
fn test_p2_skip_recovery() {
    // P0: Agent attempts to skip directly to P2 optimization
    // Expected: Room rejects tile, forces agent back to P1 channel finding
    let mut room = DeadbandRoom::new();
    let agent_id = "test_agent_1".to_string();

    // Agent submits P2 tile without P1 context
    let invalid_tile = Tile {
        agent_id: agent_id.clone(),
        phase: Phase::P2,
        content: "Optimizing path without safe channel".to_string(),
        timestamp: Utc::now(),
    };

    let result = room.submit_tile(invalid_tile);
    assert!(result.is_err());
    assert_eq!(result.unwrap_err(), RoomError::ProtocolViolation);

    // Verify agent state reset to P1
    let agent_state = room.get_agent_state(&agent_id);
    assert_eq!(agent_state.current_phase, Phase::P1);
}
